 No PID available.
 </div>
 </div>
 </div>
 </div> */}

                        {/* <div className="card-footer pidSysWidget">
 <div id="pidReviewStatus">
 <div className="text-muted pb-3">
 <i className="fa fa-fw fa-info-square pr-4"></i>
 Currently, this PID is not undergoing Customer
 review.
 </div>{" "}
 </div>
 </div> */}
                      </form>
                    </div>
                  </div>
                </div>
              </div>

              <div
                className="tab-pane fade"
                id="profile-1"
                role="tabpanel"
                aria-labelledby="profile-tab"
              >
                <div
                  className="card card_product_detail_certificates"
                  style={{ border: "1px solid #dbdbd9" }}
                >
                  <div className="card-header d-flex justify-content-between align-items-center">
                    <div>
                      <i className="fa fa-lg fa-fw fa-file-certificate"></i>{" "}
                      Certificates
                    </div>
                    <Button
                      variant="primary"
                      onClick={() => setShowCertificateModal(true)}
                    >
                      Assign Certificate
                    </Button>
                  </div>
                  <div className="card-body">
                    <div className="table-responsive">
                      {loadingCert ? (
                        <div className="text-center">
                          Loading certificates...
                        </div>
                      ) : (
                        <table className="table table-hover table-striped">
                          <thead className="thead-light">
                            <tr>
                              <th width="72"></th>
                              <th className="column-min-width-110">
                                <span>Country</span>
                              </th>
                              <th className="column-min-width-110 text-center">
                                <span>Cert.D.</span>
                              </th>
                              <th className="column-min-width-110 text-center">
                                <span>Exp.D.</span>
                              </th>
                              <th className="column-min-width-110 text-center">
                                <span>Status</span>
                              </th>
                              <th className="column-min-width-110 text-center">
                                <span>Progress</span>
                              </th>
                              <th className="column-min-width-110 text-center">
                                <span>Certificate</span>
                              </th>
                              <th className="text-center column-min-width-90">
                                <span>Com.</span>
                              </th>
                            </tr>
                          </thead>
                          <tbody>
                            {certificates.map((cert) => {
                              const progress = getProgressPercentage(
                                cert.c_status
                              );
                              const progressColor = getProgressColor(
                                cert.c_status
                              );
                              return (
                                <tr key={cert.n_certificate_id}>
                                  <td>
                                    <a
                                      className="btn btn-sm btn-outline-gray-500"
                                      href="#"
                                      title="Cert Files"
                                    >
                                      <i className="fas fa-search"></i>
                                    </a>
                                    <a
                                      className="btn btn-sm btn-outline-gray-500"
                                      href="#"
                                      title="Info"
                                    >
                                      <i className="fas fa-info"></i>
                                    </a>
                                  </td>
                                  <td>
                                    {countryNames[cert.n_country_id] ||
                                      "Loading..."}
                                  </td>
                                  <td className="text-center">
                                    {cert.c_cert_date}
                                  </td>
                                  <td className="text-center">
                                    {cert.c_exp_date}
                                  </td>
                                  <td className="text-center">
                                    <span
                                      className={`fa fa-lg fa-fw fa-star ${getStatusColor(
                                        cert.c_status
                                      )}`}
                                    ></span>
                                  </td>
                                  <td className="text-center">
                                    <div
                                      className="progress"
                                      style={{
                                        height: "20px",
                                        width: "100px",
                                        margin: "0 auto",
                                      }}
                                    >
                                      <div
                                        className={`progress-bar ${progressColor}`}
                                        role="progressbar"
                                        style={{ width: `${progress}%` }}
                                        aria-valuenow={progress}
                                        aria-valuemin="0"
                                        aria-valuemax="100"
                                      >
                                        {progress}%
                                      </div>
                                    </div>
                                  </td>
                                  <td className="text-center">
                                    <a
                                      className="ibl-lightbox"
                                      href="#"
                                      style={{ cursor: "pointer" }}
                                    >
                                      <span
                                        className="fa fa-lg fa-fw far fa-file-alt"
                                        style={{ color: "#666666" }}
                                      ></span>
                                    </a>
                                  </td>
                                  <td className="text-center">
                                    <span
                                      className="fa fa-lg fa-fw fa-comment"
                                      style={{
                                        color: "#666666",
                                        cursor: "pointer",
                                      }}
                                      onClick={() =>
                                        handleShowComments(cert.c_comments)
                                      }
                                      title="View Comments"
                                    ></span>
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              <div
                className="tab-pane fade"
                id="profile-3"
                role="tabpanel"
                aria-labelledby="profile-tab"
              >
                <div
                  className="card card_product_detail_certificates"
                  style={{ border: "1px solid #dbdbd9" }}
                >
                  <div
                    className="card-header"
                    data-tour="true"
                    data-step="1"
                    data-intro="Here you can see a list of all certificates in this product. The number in brackets shows how many certificates there are."
                  >
                    <i className="fa fa-lg fa-fw fa-file-certificate"></i> Test
                    Reports
                  </div>
                  <div className="card-body">
                    <div className="table-responsive">
                      <div style={{ textAlign: "right" }}>
                        <Button
                          variant="contained"
                          color="primary"
                          startIcon={<span>+</span>}
                          onClick={() => setShowTestReportModal(true)}
                        >
                          Add Test Report
                        </Button>
                      </div>

                      {loading ? (
                        <div className="text-center">Loading...</div>
                      ) : (
                        <table className="table table-hover table-striped mb-3">
                          <thead className="thead-light">
                            <tr>
                              <th width="5%">
                                <input type="checkbox" />
                              </th>
                              <th width="35%">Exhibit Name</th>
                              <th width="15%">File Category</th>
                              <th width="10%">Filetype</th>
                              <th width="10%">Date</th>
                              <th width="10%">Uploaded by</th>
                              <th width="10%">Allow Deletion</th>
                              <th width="10%" className="text-right"></th>
                            </tr>
                          </thead>
                          <tbody>
                            {testReports.map((report) => (
                              <tr
                              // key={client.clientId}
                              // onClick={() => handleRowClick(client)}
                              // style={{ cursor: "pointer" }}
                              >
                                <td>
                                  <input type="checkbox" />
                                </td>

                                <td>
                                  <a
                                    href=""
                                    onClick={handleViewPDF}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                  >
                                    {report.c_rep_name}
                                  </a>
                                </td>
                                <td>{report.c_file_cat_name}</td>

                                <td>
                                  <div>application/pdf</div>
                                  <div className="small text-muted">
                                    0.03 MB
                                  </div>
                                </td>
                                <td>2025-03-25 01:50:09</td>
                                <td>richa@c-prav.com</td>
                                <td>
                                  <input type="checkbox" />
                                </td>
                                <td className="text-right buttons">
                                  <a
                                    className="btn btn-sm btn-outline-gray-500 mr-1"
                                    title="Edit Testreport"
                                  >
                                    <i className="fa fa-fw fa-edit"></i>
                                  </a>
                                  <a
                                    className="btn btn-sm btn-outline-gray-500 mr-1"
                                    title="Archive Testreport"
                                  >
                                    <i className="fa fa-fw fa-archive"></i>
                                  </a>
                                  {roles.includes("admin") && (
                                    <Button
                                      variant="link"
                                      className="text-danger p-0"
                                      // onClick={(e) =>
                                      // handleDeleteClick(client, e)
                                      // }
                                    >
                                      <FaTrash />
                                    </Button>
                                  )}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Comments Modal */}
      <Modal show={showComments} onHide={handleCloseComments} centered>
        <Modal.Header closeButton>
          <Modal.Title>Certificate Comments</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>{selectedComments}</p>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseComments}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Certificate Assignment Modal */}
      <Modal
        show={showCertificateModal}
        onHide={() => setShowCertificateModal(false)}
        size="lg"
      >
        <Modal.Header closeButton>
          <Modal.Title>Assign New Certificate</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleSaveCertificate}>
            <Form.Group className="mb-3">
              <Form.Label>Country</Form.Label>
              <Form.Select
                name="n_country_id"
                value={certificateForm.n_country_id}
                onChange={handleCertificateInputChange}
                required
              >
                <option value="">Select Country</option>
                {countries.map((country) => (
                  <option key={country.countryId} value={country.countryId}>
                    {country.country}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Certificate Date</Form.Label>
              <DatePicker
                selected={certificateForm.c_cert_date}
                onChange={(date) => handleDateChange(date, "c_cert_date")}
                className="form-control"
                dateFormat="yyyy-MM-dd"
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Expiration Date</Form.Label>
              <DatePicker
                selected={certificateForm.c_exp_date}
                onChange={(date) => handleDateChange(date, "c_exp_date")}
                className="form-control"
                dateFormat="yyyy-MM-dd"
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Status</Form.Label>
              <Form.Select
                name="c_status"
                value={certificateForm.c_status}
                onChange={handleCertificateInputChange}
                required
              >
                <option value="Approved">Approved</option>
                <option value="In Progress">In Progress</option>
                <option value="Ends Soon">Ends Soon</option>
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Certificate File (PDF)</Form.Label>
              <Form.Control
                type="file"
                accept=".pdf"
                onChange={handleFileChange}
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Comments</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                name="c_comments"
                value={certificateForm.c_comments}
                onChange={handleCertificateInputChange}
                required
              />
            </Form.Group>

            <div className="text-end">
              <Button
                variant="secondary"
                onClick={() => setShowCertificateModal(false)}
                className="me-2"
              >
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                Save
              </Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>

      {/* Test Report Modal */}
      <Modal
        show={showTestReportModal}
        onHide={() => setShowTestReportModal(false)}
        size="lg"
      >
        <Modal.Header closeButton>
          <Modal.Title>Add Test Report</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleSaveTestReport}>
            <Form.Group className="mb-3">
              <Form.Label>Uploaded By</Form.Label>
              <Form.Control
                type="text"
                value={testReportForm.c_uploaded_by}
                readOnly
                disabled
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>File Category</Form.Label>
              <Form.Select
                name="c_file_cat_name"
                value={testReportForm.c_file_cat_name}
                onChange={handleTestReportInputChange}
                required
              >
                <option value="Test Report EMC">Test Report EMC</option>
                <option value="Test Report RF">Test Report RF</option>
                <option value="Test Report Safety">Test Report Safety</option>
                <option value="Test Report Health">Test Report Health</option>
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>File Type</Form.Label>
              <Form.Control type="text" value="PDF" readOnly disabled />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Date</Form.Label>
              <Form.Control
                type="text"
                value={testReportForm.d_date}
                readOnly
                disabled
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Test Report File (PDF)</Form.Label>
              <Form.Control
                type="file"
                accept=".pdf"
                onChange={handleTestReportFileChange}
                required
              />
            </Form.Group>

            <div className="text-end">
              <Button
                variant="secondary"
                onClick={() => setShowTestReportModal(false)}
                className="me-2"
              >
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                Save
              </Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>
    </div>
  );
};

export default CertDB_ProductInfo;
